query:
NODE VALUE out_degree SumAgg<INT64> = 0
TABLE result_table {id STRING, degree INT64}

MATCH (s:player)-[e:follow]->(t:player)
PER PATH {
  SET s.@out_degree += 1
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id, p.@out_degree INTO result_table
}

FOR row IN result_table
RETURN row.id AS id, row.degree AS degree
